import{VAPID_PUBLIC_KEY,api}from"./api.js";function urlBase64ToUint8Array(r){const e=(r+"=".repeat((4-r.length%4)%4)).replace(/-/g,"+").replace(/_/g,"/"),i=atob(e);return Uint8Array.from([...i].map(r=>r.charCodeAt(0)))}export function isPushSupported(){return"serviceWorker"in navigator&&"PushManager"in window&&"Notification"in window}export async function getPushSubscription(){if(!("serviceWorker"in navigator))return null;try{const r=await navigator.serviceWorker.ready;return await r.pushManager.getSubscription()}catch{return null}}export async function subscribePush(){if(!api.isLoggedIn())throw new Error("Harus login terlebih dahulu");let r=Notification.permission;if("denied"===r)throw new Error("Izin notifikasi telah ditolak. Aktifkan di pengaturan browser.");if("granted"!==r&&(r=await Notification.requestPermission(),"granted"!==r))throw new Error("Izin notifikasi ditolak");const e=await navigator.serviceWorker.ready,i=await e.pushManager.subscribe({userVisibleOnly:!0,applicationServerKey:urlBase64ToUint8Array(VAPID_PUBLIC_KEY)});return await api.subscribePush(i),localStorage.setItem("pushSubscribed","true"),i}export async function unsubscribePush(){const r=await getPushSubscription();if(r){try{await api.unsubscribePush(r.endpoint)}catch{}await r.unsubscribe(),localStorage.removeItem("pushSubscribed")}else localStorage.removeItem("pushSubscribed")}export function isPushSubscribed(){return"true"===localStorage.getItem("pushSubscribed")}